export type ConnectorCategory = 'erp' | 'crm' | 'ecommerce' | 'accounting' | 'automation' | 'payment';
export type ConnectorAvailability = 'full' | 'coming_soon';

export interface ConnectorEntityConfig {
  type: string;
  label: string;
  erpObjectName: string;
  targetModule: 'sales' | 'offers' | 'contacts' | 'purchases' | 'inventory-services';
  expectedSchema: object;
  responseTemplate: object;
  templateSlug: string;
}

export interface ConnectorDefinition {
  id: string;
  name: string;
  vendor: string;
  category: ConnectorCategory;
  description: string;
  logo: string;
  color: string;
  isPopular: boolean;
  availability: ConnectorAvailability;
  entities: ConnectorEntityConfig[];
  setupInstructions: string[];
  docUrl?: string;
  signatureHeader?: string;
}

